/** The mathematical formula that defines how the prices of NFTs change after each buy or sell within a pool. */
export enum BondingCurveType {
  Exponential = 'EXPONENTIAL',
  Gda = 'GDA',
  Linear = 'LINEAR',
  Xyk = 'XYK'
}

/** A bucket identifier for grouping and querying webhooks. Provide both fields together so bucket-based queries work correctly. */
export type BucketKeyInput = {
  /** The bucket ID for the webhook. */
  bucketId: Scalars['String']['input'];
  /** The bucket sort key for the webhook. */
  bucketSortKey: Scalars['String']['input'];
};

/** Event data for a token burn event. */
export type BurnEventData = {
  __typename?: 'BurnEventData';
  /** The amount of `token0` removed from the pair. */
  amount0?: Maybe<Scalars['String']['output']>;
  /** The amount of `token0` removed from the pair, adjusted by the number of decimals in the token. For example, if `amount0` is in WEI, `amount0Shifted` will be in ETH. */
  amount0Shifted?: Maybe<Scalars['String']['output']>;
  /** The amount of `token1` removed from the pair. */
  amount1?: Maybe<Scalars['String']['output']>;
  /** The amount of `token1` removed from the pair, adjusted by the number of decimals in the token. For example, USDC `amount1Shifted` will be by 6 decimals. */
  amount1Shifted?: Maybe<Scalars['String']['output']>;
  /** The lower tick boundary of the position. Only applicable for UniswapV3 events. */
  tickLower?: Maybe<Scalars['String']['output']>;
  /** The upper tick boundary of the position. Only applicable for UniswapV3 events. */
  tickUpper?: Maybe<Scalars['String']['output']>;
  /** The type of token event, `Burn`. */
  type: EventType;
};

export type Category = {
  __typename?: 'Category';
  /**
   * The category banner image URL.
   * @deprecated Categories no longer carry imagery. Will be null.
   */
  bannerUrl?: Maybe<Scalars['String']['output']>;
  /** A short description of the category. */
  description?: Maybe<Scalars['String']['output']>;
  /**
   * The category icon URL.
   * @deprecated Categories no longer carry imagery. Will be null.
   */
  iconUrl?: Maybe<Scalars['String']['output']>;
  /** The category id — a stable slug (also the value stored on tokens). */
  id: Scalars['String']['output'];
  /** The number of tokens currently assigned to the category. Null when the count has not been computed yet. */
  memberCount?: Maybe<Scalars['Int']['output']>;
  /** The display name. For example, `Artificial Intelligence`. */
  name: Scalars['String']['output'];
  /** The parent category id, for hierarchical categories. */
  parentId?: Maybe<Scalars['String']['output']>;
  /** An optional short name/abbreviation for compact surfaces (pills, badges). For example, `AI`. Null when unset — the API does not fall back to `name`; clients decide whether to. */
  shortName?: Maybe<Scalars['String']['output']>;
  /** The URL slug (same value as `id`). */
  slug: Scalars['String']['output'];
  /** The lifecycle status of the category. */
  status: CategoryStatus;
  /** Whether the category is canonical or narrative. */
  type: CategoryType;
};

export enum CategoryStatus {
  Active = 'ACTIVE',
  Archived = 'ARCHIVED',
  Draft = 'DRAFT'
}

export type CategoryTokenConnection = {
  __typename?: 'CategoryTokenConnection';
  /** The number of tokens returned. */
  count?: Maybe<Scalars['Int']['output']>;
  /** Where in the list the server started when returning items. */
  page?: Maybe<Scalars['Int']['output']>;
  /** The list of tokens in the category matching the filter parameters. */
  results?: Maybe<Array<Maybe<TokenFilterResult>>>;
};

export enum CategoryType {
  /** Objective, long-lived groupings (DeFi, L1, stablecoins). */
  Canonical = 'CANONICAL',
  /** Trend-driven groupings (AI, RWA, memes). */
  Narrative = 'NARRATIVE'
}

