  outcome0AskUSD: Scalars['String']['output'];
  /** The bid CT of the outcome 0. */
  outcome0BidCT: Scalars['String']['output'];
  /** The bid USD of the outcome 0. */
  outcome0BidUSD: Scalars['String']['output'];
  /** The label of the outcome 0. */
