/** How much contract analysis stood behind a verdict. This describes what was looked at, not what was concluded — `ANALYZED` does not mean a token is safe. */
export enum RiskAnalysisCoverage {
  /** Analysis ran and reached a decisive verdict. */
  Analyzed = 'ANALYZED',
  /** Analysis ran but reached no decisive verdict. */
  Inconclusive = 'INCONCLUSIVE',
  /** No contract analysis stands behind this assessment. */
  NotAnalyzed = 'NOT_ANALYZED'
}

/** The reasons a risk verdict can cite. This vocabulary grows over time. Treat the list on a token as the reasons Codex can name today, not as a complete account of everything wrong with it. */
export enum RiskReasonCode {
  AuthCanTransferOwnership = 'AUTH_CAN_TRANSFER_OWNERSHIP',
  AuthFreeze = 'AUTH_FREEZE',
  AuthMint = 'AUTH_MINT',
  AuthOwnerNotRenounced = 'AUTH_OWNER_NOT_RENOUNCED',
  AuthPausable = 'AUTH_PAUSABLE',
  AuthPermanentDelegate = 'AUTH_PERMANENT_DELEGATE',
  AuthTransferHook = 'AUTH_TRANSFER_HOOK',
  FlowBundledLaunch = 'FLOW_BUNDLED_LAUNCH',
  FlowMechanicalTrading = 'FLOW_MECHANICAL_TRADING',
  FlowOneWay = 'FLOW_ONE_WAY',
  FlowRingDominated = 'FLOW_RING_DOMINATED',
  FlowWalletFarm = 'FLOW_WALLET_FARM',
  FlowWashDominated = 'FLOW_WASH_DOMINATED',
  HoldBundlerHeavy = 'HOLD_BUNDLER_HEAVY',
  HoldDevHeavy = 'HOLD_DEV_HEAVY',
  /** The creator of a launchpad token sold or handed off a large share of supply in the token's first hour. */
  HoldInsiderDumped = 'HOLD_INSIDER_DUMPED',
  HoldInsiderHeavy = 'HOLD_INSIDER_HEAVY',
  HoldSniperHeavy = 'HOLD_SNIPER_HEAVY',
  HoldTop10Concentrated = 'HOLD_TOP10_CONCENTRATED',
  LabelManualScam = 'LABEL_MANUAL_SCAM',
  LabelVerified = 'LABEL_VERIFIED',
  LiqDraining = 'LIQ_DRAINING',
  LiqMinimal = 'LIQ_MINIMAL',
  LiqRugCliff = 'LIQ_RUG_CLIFF',
  LiqUnknown = 'LIQ_UNKNOWN',
  LiqUnlocked = 'LIQ_UNLOCKED',
  ProofDefaultFrozen = 'PROOF_DEFAULT_FROZEN',
  ProofHoneypotSim = 'PROOF_HONEYPOT_SIM',
  ProofNonTransferable = 'PROOF_NON_TRANSFERABLE',
  ProofPaused = 'PROOF_PAUSED',
  ProofRugOccurred = 'PROOF_RUG_OCCURRED',
  ProofTransferFee_100 = 'PROOF_TRANSFER_FEE_100',
  RepImitatorName = 'REP_IMITATOR_NAME',
  RepImitatorSymbol = 'REP_IMITATOR_SYMBOL',
  RepRiskyCreator = 'REP_RISKY_CREATOR',
  RepScammerFunded = 'REP_SCAMMER_FUNDED',
  RepSerialRugger = 'REP_SERIAL_RUGGER',
  TaxBuyHigh = 'TAX_BUY_HIGH',
  TaxHoneypotUnconfirmed = 'TAX_HONEYPOT_UNCONFIRMED',
  TaxPaused = 'TAX_PAUSED',
  TaxSellHigh = 'TAX_SELL_HIGH'
}

/** A token's risk verdict. These values are not an ordered safety scale: `SCAM` and `VERIFIED` are terminal states reached by mechanical proof or a human decision, while `HIGH_RISK`, `CAUTION` and `NEUTRAL` are graded outcomes of weighted signals. */
export enum RiskVerdict {
  /** The weighted score reached the caution threshold but remains below high risk. */
  Caution = 'CAUTION',
  /** The weighted score reached the high-risk threshold. */
  HighRisk = 'HIGH_RISK',
  /** The weighted score is below the caution threshold. Reasons may still be present. Not a statement that the token is safe. */
  Neutral = 'NEUTRAL',
  /** Proven a scam by mechanical evidence, or labelled one by a human. */
  Scam = 'SCAM',
  /** A human marked this token not-a-scam. A moderator judgement, not an allowlist. */
  Verified = 'VERIFIED',
  /** Marked not-a-scam by a human, but mechanical signals disagree. */
  VerifiedContested = 'VERIFIED_CONTESTED'
}

