/** Wallet labels. Used for filtering wallets with `includeLabels` and `excludeLabels`. */
export enum WalletLabel {
  /** On our internal blacklist. */
  Blacklisted = 'BLACKLISTED',
  /** Automated trading bot: proven by arbitrage inside its own transactions, or inferred from its trading cadence. Its confidence is `botScore`. */
  Bot = 'BOT',
  /** Cross-chain bridge contract. */
  Bridge = 'BRIDGE',
  /** Centralized exchange wallet. */
  Cex = 'CEX',
  /** Decentralized exchange wallet. */
  Dex = 'DEX',
  /** Project founder wallet. */
  Founder = 'FOUNDER',
  /** Exploited a contract. */
  Hacker = 'HACKER',
  /** Pre-launch insider buyer. */
  Insider = 'INSIDER',
  /** Wallet is interesting (based on a number of factors). */
  Interesting = 'INTERESTING',
  /** Key opinion leader / influencer. */
  Kol = 'KOL',
  /** Wallet holds $5M+ in assets. */
  MediumWealthy = 'MEDIUM_WEALTHY',
  /** Wallet holds $10M+ in assets. */
  MegaWealthy = 'MEGA_WEALTHY',
  /** MEV extraction bot. */
  MevBot = 'MEV_BOT',
  /** Privacy mixer. */
  Mixer = 'MIXER',
  /** Known rug-puller. */
  RugPuller = 'RUG_PULLER',
  /** OFAC sanctioned. */
  Sanctioned = 'SANCTIONED',
  /** Wallet behind token scams: a serial rug deployer, its launch crew, or a honeypot creator. Its confidence is `scammerScore`. */
  Scammer = 'SCAMMER',
  /** Wallet has made over $7.5K profit in the last 90 days trading tokens that are older than 2 days. */
  SmartTraderTokensOverTwoDaysOld = 'SMART_TRADER_TOKENS_OVER_TWO_DAYS_OLD',
  /** Wallet has made over $5K profit in the last 90 days trading tokens that are between 1 hour and 2 days old. */
  SmartTraderTokensUnderTwoDaysOld = 'SMART_TRADER_TOKENS_UNDER_TWO_DAYS_OLD',
  /** Wallet has made over $3K profit in the last 90 days trading tokens that were launched within their first hour. */
  Sniper = 'SNIPER',
  /** Venture capital fund. */
  Vc = 'VC',
  /** Operator-run wallet that trades to manufacture a token's volume: one a volume-bot platform runs, or one of hundreds a single funder seeded to churn one pool. */
  VolumeBot = 'VOLUME_BOT',
  /** Wallet holds $1M+ in assets. */
  Wealthy = 'WEALTHY',
  /** High-balance / high-volume wallet. */
  Whale = 'WHALE'
}

/** Metadata for a wallet label from the WALLET_LABEL_TYPES vocabulary */
export type WalletLabelType = {
  __typename?: 'WalletLabelType';
  /** Description of what this label means */
  description: Scalars['String']['output'];
  /** Human-readable display name */
  displayName: Scalars['String']['output'];
  /** Label name (e.g. WHALE, CEX, KOL) */
  name: Scalars['String']['output'];
};

